90	// Prim's minimum spanning tree: each star joins its nearest branch, which is
91	// why real star charts look calm instead of criss-crossed. Exported so the
92	// waitlist lens draws its figure with the same math a person's own card uses.
93	export function spanningTree(points: Array<{ x: number; y: number }>): Array<[number, number]> {
94	  const inTree = [0];
95	  const edges: Array<[number, number]> = [];
96	  while (inTree.length < points.length) {
97	    let best: { i: number; j: number; d: number } | null = null;
98	    for (const i of inTree) {
99	      for (let j = 0; j < points.length; j++) {
100	        if (inTree.includes(j)) continue;
101	        const dx = points[i].x - points[j].x;
102	        const dy = points[i].y - points[j].y;
103	        const d = dx * dx + dy * dy;
104	        if (best === null || d < best.d) best = { i, j, d };
105	      }
106	    }
107	    if (best === null) break;
108	    edges.push([best.i, best.j]);
109	    inTree.push(best.j);
110	  }
111	  return edges;
112	}
