114	export function buildSky(name: string, handle?: string): SkyData {
115	  const rand = seededRandom(hashString(name + (handle ?? "")));
116	  const hues = personHues(name, handle);
117	
118	  const nebulae = [
119	    { cx: W * 0.35, cy: H * 0.25, rx: W * 0.75, ry: H * 0.42, hue: hues[0], alpha: 0.18 },
120	    { cx: W * 0.75, cy: H * 0.5, rx: W * 0.65, ry: H * 0.36, hue: hues[1], alpha: 0.15 },
121	    { cx: W * 0.4, cy: H * 0.7, rx: W * 0.6, ry: H * 0.3, hue: hues[2], alpha: 0.13 },
122	  ];
123	
124	  // Depth: many faint stars on a power law -- the difference between a
125	  // diagram and a sky.
126	  const minors: SkyStar[] = [];
127	  for (let i = 0; i < MINOR_COUNT; i++) {
128	    const hi = 0.25 + rand() * 0.55;
129	    minors.push({
130	      x: rand() * W,
131	      y: rand() * H,
132	      r: 0.4 + Math.pow(rand(), 2.6) * 1.4,
133	      hi,
134	      lo: Math.max(0.08, hi - 0.3),
135	      dur: 2.6 + rand() * 4.5,
136	      delay: rand() * 6,
137	      rvd: rand(),
138	    });
139	  }
140	
141	  // A few colored giants, like a telescope frame.
142	  const giants: SkyMajor[] = [];
143	  for (let i = 0; i < 5; i++) {
144	    giants.push({
145	      x: PAD + rand() * (W - PAD * 2),
146	      y: PAD + rand() * (H * 0.8),
147	      r: 1.2 + rand(),
148	      hue: hues[i % 3],
149	      hi: 0.9,
150	      lo: 0.5,
151	      dur: 3 + rand() * 3,
152	      delay: rand() * 4,
153	      rvd: rand(),
154	    });
155	  }
156	
157	  const placed = placeMajors(rand, 7 + Math.floor(rand() * 2));
158	  const edges = spanningTree(placed);
159	  const majors: SkyMajor[] = placed.map((p, i) => ({
160	    x: p.x,
161	    y: p.y,
162	    r: 1.5 + rand() * 1.9,
163	    hue: hues[i % 3],
164	    hi: 1,
165	    lo: 0.62,
166	    dur: 3 + rand() * 3.4,
167	    delay: rand() * 5,
168	    rvd: rand(),
169	  }));
170	
171	  // The two brightest stars in the figure earn diffraction flares.
172	  const byBrightness = majors
173	    .map((m, i) => ({ r: m.r, i }))
174	    .sort((a, b) => b.r - a.r)
175	    .slice(0, 2);
176	  const flares = byBrightness.map(({ r, i }) => ({
177	    x: majors[i].x,
178	    y: majors[i].y,
179	    len: r * 9,
180	    dur: 4 + rand() * 3,
181	    delay: rand() * 4,
182	  }));
183	
184	  const sx = 40 + rand() * 160;
185	  const sy = 30 + rand() * 120;
186	  const shoot = { x1: sx, y1: sy, x2: sx - 34, y2: sy - 19, delay: 3 + rand() * 8 };
187	
188	  // Pick the featured minors LAST -- after every other draw above -- so the
189	  // giants, constellation, flares and shooting star stay byte-identical to
190	  // before this flag existed. Drawing here shifts no earlier value, so no
191	  // figure moves; only the boolean on the chosen minors changes. Partial
192	  // Fisher-Yates over the same seeded stream keeps the pick stable per person.
193	  const order = minors.map((_, i) => i);
194	  const featureCount = Math.min(FEATURED_MINORS, order.length);
195	  for (let i = 0; i < featureCount; i++) {
196	    const j = i + Math.floor(rand() * (order.length - i));
197	    [order[i], order[j]] = [order[j], order[i]];
198	    minors[order[i]].featured = true;
199	  }
200	
201	  return { width: W, height: H, pad: PAD, hues, nebulae, minors, giants, majors, edges, flares, shoot };
202	}
