215	// A person's constellation shrunk to a map cluster. It reuses buildSky's
216	// majors + edges so the figure on the atlas is recognizably the SAME shape as
217	// on their card and detail sky -- identity, not decoration. Minors are dropped;
218	// the shared dust field carries the faint-star texture instead.
219	export function buildCluster(
220	  name: string,
221	  handle?: string,
222	  opts?: { width?: number; height?: number; pad?: number },
223	): ClusterData {
224	  const width = opts?.width ?? 120;
225	  const height = opts?.height ?? 92;
226	  const pad = opts?.pad ?? 8;
227	  const sky = buildSky(name, handle);
228	
229	  const xs = sky.majors.map((m) => m.x);
230	  const ys = sky.majors.map((m) => m.y);
231	  const minX = Math.min(...xs);
232	  const maxX = Math.max(...xs);
233	  const minY = Math.min(...ys);
234	  const maxY = Math.max(...ys);
235	  // Guard the degenerate single-column/row case so we never divide by zero.
236	  const spanX = maxX - minX || 1;
237	  const spanY = maxY - minY || 1;
238	  const innerW = Math.max(0, width - pad * 2);
239	  const innerH = Math.max(0, height - pad * 2);
240	
241	  const stars: ClusterStar[] = sky.majors.map((m) => ({
242	    x: pad + ((m.x - minX) / spanX) * innerW,
243	    y: pad + ((m.y - minY) / spanY) * innerH,
244	    // Map the card radius (~1.5..3.4) into a small, readable map radius.
245	    r: 1.1 + (m.r - 1.5) * 0.5,
246	    hue: m.hue,
247	  }));
248	
249	  return { width, height, stars, edges: sky.edges };
250	}
