262	// One shared field of faint background stars behind every cluster -- seeded
263	// from a fixed string, NOT per person, so the whole sky twinkles as one. Unit
264	// coordinates keep it resolution-independent across resizes.
265	export function buildDust(count = 80, seed = "haven-atlas-dust"): DustStar[] {
266	  const rand = seededRandom(hashString(seed));
267	  const dust: DustStar[] = [];
268	  for (let i = 0; i < count; i++) {
269	    dust.push({
270	      x: rand(),
271	      y: rand(),
272	      r: 0.4 + rand() * 0.7,
273	      // Deliberately dim: dust must never compete with a person's stars.
274	      hi: 0.18 + rand() * 0.16,
275	      lo: 0.06 + rand() * 0.06,
276	      dur: 3 + rand() * 4,
277	      delay: rand() * 4,
278	    });
279	  }
280	  return dust;
281	}
