283	// Golden-angle spiral placement, ordered by the recent-first query: index 0
284	// (newest) sits nearest the center, each later person spirals outward. The y
285	// radius is squashed so the field reads as a wide sky rather than a disc.
286	// maxR is capped so the outermost cluster's full box + label never leaves the
287	// viewport -- the layout, not the caller, owns staying in bounds.
288	export function atlasLayout(
289	  count: number,
290	  width: number,
291	  height: number,
292	  opts?: {
293	    boxW?: number;
294	    boxH?: number;
295	    labelH?: number;
296	    centerYOffset?: number;
297	  },
298	): Array<{ x: number; y: number }> {
299	  const boxW = opts?.boxW ?? 120;
300	  const boxH = opts?.boxH ?? 92;
301	  const labelH = opts?.labelH ?? 46;
302	  const centerYOffset = opts?.centerYOffset ?? 14;
303	
304	  const cx = width / 2;
305	  const cy = height / 2 + centerYOffset;
306	  const squash = 0.82;
307	
308	  // Room the outermost cluster needs on each side (label only hangs below).
309	  const marginX = boxW / 2 + 8;
310	  const marginTop = boxH / 2 + 8;
311	  const marginBottom = boxH / 2 + labelH + 8;
312	
313	  const maxRx = Math.min(cx - marginX, width - cx - marginX);
314	  const maxRy = Math.min(cy - marginTop, height - cy - marginBottom) / squash;
315	  const maxR = Math.max(0, Math.min(maxRx, maxRy, Math.min(width, height) * 0.42));
316	
317	  const n = Math.max(count, 1);
318	  const points: Array<{ x: number; y: number }> = [];
319	  for (let i = 0; i < count; i++) {
320	    const angle = i * 2.399963; // golden angle in radians
321	    const rad = maxR * Math.sqrt((i + 0.7) / n);
322	    points.push({
323	      x: cx + Math.cos(angle) * rad,
324	      y: cy + Math.sin(angle) * rad * squash,
325	    });
326	  }
327	  return points;
328	}
